from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def sort(self, arr):
        # Template method: define the skeleton
        n = len(arr)
        for i in range(n):
            self.compare_and_swap(arr, i)
        return arr

    @abstractmethod
    def compare_and_swap(self, arr, i):
        # Abstract method: compare and swap logic
        pass

class BubbleSort(SortAlgorithm):
    def compare_and_swap(self, arr, i):
        n = len(arr)
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]

class SelectionSort(SortAlgorithm):
    def compare_and_swap(self, arr, i):
        n = len(arr)
        min_idx = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]

# Testing it out!
if __name__ == "__main__":
    data = [64, 34, 25, 12, 22, 11, 90]
    print("Original:", data)
    bubble = BubbleSort()
    print("Bubble Sort:", bubble.sort(data.copy()))
    selection = SelectionSort()
    print("Selection Sort:", selection.sort(data.copy()))
